INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 2, 5, 'go',
  'Driest stretch. 20-30C. Maha Shivaratri Feb 14 — major Pancha Bhoota Wind-element fest.',
  'February is the driest month. Daytime 29-30C, rainfall under 20mm. Maha Shivaratri Feb 14 2026 — major festival at the Pancha Bhoota Wind-element Stalam. Rahu-Ketu puja queues climb sharply pre-festival fortnight.',
  NULL,
  'February in Srikalahasti is the technical peak. Rainfall under 20mm, daytime 29-30C, nights 20-21C, humidity 55 percent — the Rayalaseema-coastal-fringe transition zone at its driest. The Sri Kalahastiswara Swamy Temple at full ritual tempo. Maha Shivaratri falls February 14 in 2026 — among the five Pancha Bhoota Stalams, Srikalahasti''s Shivaratri is one of the three definitional Shiva festivals here alongside the Karthika-Deepam and Shivaratri at Kashi. The temple runs a 24-hour ritual schedule across the festival day; the four-pahar Rudrabhishekam sequence at 6pm/9pm/midnight/3am draws sequential pilgrim waves. Festival-day total: 150,000-250,000 darshan-takers. Rahu-Ketu Sarpa Dosha pujas (4 tiers ₹250-2,500) at full schedule; the 6-9am Rahu Kalam window books out 2-3 weeks ahead through February. Patala Ganapati shrine and the Dakshinamurthy shrine within the temple complex run their standard sequences. Kalamkari workshops — the 15th-century pen-only Srikalahasti tradition distinct from Machilipatnam''s block-print version — at full output.'
)
