INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 3, 4, 'go',
  'Last cool month. 22-33C. Rahu-Ketu pujas workable through morning. Hotel rates ease 20 percent.',
  'March is the soft-landing month. Daytime climbs 31-33C. Rahu-Ketu pujas workable mornings; afternoon temple circulation compresses. Hotel rates ease 20 percent. Last clean-comfort window before April heat.',
  NULL,
  'March in Srikalahasti is the transition month. Daytime 31-33C, nights 22-23C, humidity 60 percent, rainfall under 30mm. The Sri Kalahastiswara Swamy Temple at full ritual tempo — the cool stone interior of the Wind-element Pancha Bhoota Stalam holds 27-29C even through the warming month. Rahu-Ketu Sarpa Dosha pujas (Sadharana ₹250, Madhyama ₹750, Uttama ₹1,500, Visesha ₹2,500) workable cleanly through the morning 6-11am window; afternoon Rahu Kalam timing slots see queue density but the cool sanctum offers shelter. Patala Ganapati shrine (underground Ganesha) and Dakshinamurthy shrine at standard schedule. The Sahasralinga shrine (the thousand-Shiva-linga panel inside the temple complex) at full visibility. Kalamkari workshops — APCO Co-operative on Tirupati Road, Sri Padmavathi workshop near temple — at full output; the natural dye process for Kalamkari needs the dry pre-monsoon air, so March-May is technically a productive output month even as visitor comfort drops. Vana Durga Temple (3km from main temple, the local Durga shrine) workable mornings. Hotel rates ease 20 percent off February: APCO budget rooms ₹1,200-2,200, temple-side guest houses ₹1,600-3,000.'
)
