INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 4, 3, 'wait',
  'Heat ramps. 24-37C. Temple interior cool but town walks compressed. Rahu-Ketu pujas viable AM.',
  'April pushes Srikalahasti past comfort. Daytime 35-37C. Temple cool stone interior remains workable. Rahu-Ketu pujas viable 6-10am. Town walks and Kalamkari workshop visits compressed to mornings.',
  'April in Srikalahasti compresses to morning-only town circulation. Rahu-Ketu pujas workable 6-10am inside the cool sanctum. Kalamkari workshops viable mornings. October opens the proper window for the full pilgrim-and-craft experience.',
  'April in Srikalahasti is the pre-monsoon heat ramp. Daytime 35-37C, nights 24-25C, humidity 60 percent, rainfall under 40mm. The Sri Kalahastiswara Swamy Temple at full ritual tempo — the cool stone interior holds 30-32C even through the heat; the Pancha Bhoota Wind-element shrine remains a refuge through the day. Rahu-Ketu Sarpa Dosha pujas workable 6-10am and post-5pm; the 6-9am Rahu Kalam timing remains most-recommended and the queue holds through April. Patala Ganapati shrine (underground Ganesha) workable through the day. Sahasralinga shrine and Dakshinamurthy shrine at full schedule. Kalamkari workshop visits compress to morning hours; the APCO Co-operative on Tirupati Road and the smaller weaver-painter homes on Bazaar Street remain at full output but the visitor walk-through is heat-stress-limited 11am-4pm. Vana Durga Temple (3km) compressed to early morning. Hotel rates 25 percent off February peak: APCO budget rooms ₹1,000-2,000, temple-side guest houses ₹1,400-2,800. The Tirupati-Srikalahasti combined circuit works only for pilgrim itineraries that prioritize specific lunar dates; October is materially better.'
)
