INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 5, 2, 'wait',
  'Heat peak. 26-39C. Town brutal. Temple interior cool. Push to October.',
  'May is the heat peak. Daytime 38-39C. Temple cool stone interior workable through day. Town walks unsafe 11am-5pm. Hotel rates at year-low. October opens the proper window.',
  'May at Srikalahasti is the heat peak. Town circulation compresses to dawn-and-dusk; temple cool interior remains the practical refuge. The Tirupati-Srikalahasti pilgrim circuit cannot run cleanly. October opens the proper window.',
  'May in Srikalahasti is the pre-monsoon heat peak. Daytime 38-39C, nights 26-27C, humidity 55 percent, rainfall under 30mm. Pre-monsoon dust storms hit the second fortnight, knocking visibility on the Tirupati Road and the Bazaar Street walks. The Sri Kalahastiswara Swamy Temple at full ritual tempo — the cool stone interior of the Pancha Bhoota Wind-element shrine remains a workable refuge 28-30C through the mid-day. Rahu-Ketu Sarpa Dosha pujas workable in the inner-sanctum cool 6-10am and post-5pm; the 6-9am Rahu Kalam timing slot is the recommended window. Patala Ganapati shrine workable through day. Kalamkari workshop visits compressed to 6-9am morning only — the workshop spaces themselves are hot-tin-roof tin sheds and become unworkable past 10am. Vana Durga Temple (3km) impossible past 8am. Hotel rates at year-low: APCO budget rooms ₹900-1,800, temple-side guest houses ₹1,200-2,500. The trip you came for cannot happen comfortably. October-March is dramatically better. Push 5 months.'
)
