INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 6, 2, 'wait',
  'SW monsoon light. 25-34C, 70-110mm rain. Temple workable. Roads patchy. Push to October.',
  'June sees first ease. Daytime 33-34C. SW monsoon light here (Rayalaseema-coastal fringe). Temple workable. Town walks marginal mid-day. Hotel rates at off-peak. October opens the proper window.',
  'June at Srikalahasti is first ease but the SW monsoon stays light over the Rayalaseema-coastal fringe. Town walks still compress to mornings. Tirupati-Srikalahasti combined circuit not at full ease yet. October is materially better.',
  'June in Srikalahasti is the first easing month. Rainfall climbs to 70-110mm across 8-10 wet days, daytime 33-34C, nights 25-26C, humidity 75 percent — the SW monsoon onset reaches the Rayalaseema-coastal fringe in moderate form. The Sri Kalahastiswara Swamy Temple at full ritual tempo; the cool stone interior holds 28-30C. Rahu-Ketu Sarpa Dosha pujas workable in the 6am-11am window through the cooler post-storm mornings. Patala Ganapati shrine and Sahasralinga shrine at full schedule. Kalamkari workshop visits viable in the post-storm cooler windows; the natural dye process slows as humidity climbs (dyes need lower humidity to fix to cotton). Vana Durga Temple (3km) workable mornings. Tirupati-Srikalahasti combined circuit (36km west to Tirupati) still light enough at the SW onset that the road journey is clean — Tirumala 853m elevation provides better comfort if the Srikalahasti visit pairs with a Tirumala overnight. Hotel rates at off-peak: APCO budget rooms ₹1,000-1,900, temple-side guest houses ₹1,300-2,600. October opens the proper window for the full Pancha Bhoota and Kalamkari experience.'
)
