INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 7, 3, 'wait',
  'Monsoon active. 24-32C, 90-130mm rain. Aadi-Sravana Telugu pilgrim density. Town workable.',
  'July sees Telugu pilgrim density rise — Aadi-Sravana sequence starts mid-Jul. Daytime 31-32C. Temple at full schedule. Rahu-Ketu pujas at full queue. Hotel rates +15 percent off June. October still materially cleaner.',
  'July at Srikalahasti has Aadi-Sravana pilgrim density. Daytime 31-32C. Temple at full schedule. October opens dramatically cleaner weather and the post-monsoon green that Srikalahasti misses through July.',
  'July in Srikalahasti is the proper start of the easing window. Rainfall 90-130mm across 10-12 wet days, daytime 31-32C, nights 24-25C, humidity 80 percent. The Sri Kalahastiswara Swamy Temple at full ritual tempo. Aadi-month (Tamil-Telugu calendar mid-July to mid-August) brings Telugu pilgrim density at the Pancha Bhoota Wind-element shrine; the Aadi-Velli (Aadi Fridays) and Aadi-Pournami (Aadi full moon) observances draw 30,000-50,000 daily peaks. Sravana-month (the following Telugu lunar month, typically late-July through August) sees Sravana-Sukravara density. Rahu-Ketu Sarpa Dosha pujas at full schedule — Aadi-Sravana sequence is one of the year''s peak windows for Rahu-Ketu puja bookings (the astrological calendar prioritizes specific lunar windows for these pujas). Patala Ganapati, Sahasralinga, Dakshinamurthy shrines at full schedule. Kalamkari workshop visits viable in dry windows; the natural dye process pauses on heavy-humidity days. Vana Durga Temple workable mornings. Hotel rates climb 15 percent off June: APCO budget rooms ₹1,100-2,000, temple-side guest houses ₹1,500-2,800. Functional for Aadi-Sravana-locked Telugu pilgrim itineraries.'
)
