INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 8, 3, 'wait',
  'Monsoon continues. 24-31C, 80-120mm rain. Sravana-Sukravara peak. Hotel rates +20 percent.',
  'August continues the easing. Daytime 30-31C. Sravana-Sukravara (Sravana Fridays) brings peak pilgrim density. Hotel rates at +20 percent off June. October opens the proper full-trip window.',
  NULL,
  'August in Srikalahasti continues the easing pattern. Rainfall 80-120mm across 10-12 wet days, daytime 30-31C, nights 24-25C, humidity 82 percent. The Sri Kalahastiswara Swamy Temple at full ritual tempo. Sravana-month (Telugu calendar — typically mid-August through mid-September in 2026) at peak — Sravana-Sukravara (Sravana Fridays) and Sravana-Pournami (Sravana full moon) draw heavy Telugu pilgrim density; the Pancha Bhoota Wind-element shrine sees its second-most-significant non-Shivaratri pilgrim window. Rahu-Ketu Sarpa Dosha pujas at full schedule — Aadi-Sravana sequence brings concentrated Rahu-Ketu puja bookings as the lunar-astrological window aligns. Patala Ganapati shrine and the Sahasralinga panel at full schedule. Kalamkari workshop visits viable in dry windows; the APCO Co-operative on Tirupati Road runs reduced afternoon hours through the monsoon. Vana Durga Temple workable mornings. Tirupati-Srikalahasti combined circuit (36km) sees road-traffic congestion on Sravana-Sukravara peaks. Hotel rates climb 20 percent off June: APCO budget rooms ₹1,200-2,100, temple-side guest houses ₹1,600-3,000. Lock rooms 2-3 weeks ahead through Sravana.'
)
