INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 10, 5, 'go',
  'Peak window opens. 22-29C. NE monsoon arrives mid-Oct. Brahmotsavam-Tirupati spillover. Dussehra cluster.',
  'October opens the proper season. NE monsoon arrives mid-month as evening showers. Daytime 27-29C. Tirupati Salakatla Brahmotsavam tail spillover (36km west). Dussehra-Vijayadashami pilgrim density.',
  NULL,
  'October in Srikalahasti is the proper season open. The southwest monsoon completes its retreat from the Rayalaseema-coastal fringe; the northeast monsoon arrives mid-month with 120-160mm of rainfall across 8-10 wet days, mostly late-afternoon and evening showers that rinse the temple precinct without disrupting morning programmes. Daytime 27-29C, nights 22-23C, humidity 75 percent. The Sri Kalahastiswara Swamy Temple at full ritual tempo. The Tirumala Salakatla Brahmotsavam (Sep 24-Oct 2 in 2026, 36km west at Tirupati) tail brings Vaishnavite pilgrim spillover through Srikalahasti the first week as Tirumala-pilgrims combine both temples. Dussehra-Vijayadashami (Oct 19-20 in 2026, the closing of Sharad Navaratri) brings Devi-observance density at the Vana Durga Temple. Rahu-Ketu Sarpa Dosha pujas at full schedule with the 6-9am Rahu Kalam window booking 1-2 weeks ahead. Patala Ganapati shrine, Sahasralinga panel, and the Dakshinamurthy shrine at standard schedule. Kalamkari workshop visits at full output — post-monsoon humidity ease favours the natural dye process. Hotel rates climb 25 percent off September: APCO budget rooms ₹1,500-2,800, temple-side guest houses ₹1,800-3,500.'
)
