INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 11, 5, 'go',
  'NE monsoon active. 20-28C. Karthika Masam mass-deepam. Karthika Pournami peak.',
  'November is the peak-build month. NE monsoon 150-200mm in evening showers. Karthika Masam (full month) brings mass-deepam at the Pancha Bhoota Wind-element Stalam. Karthika Pournami peak pilgrim day.',
  NULL,
  'November in Srikalahasti is one of the year''s peak months. Northeast monsoon active with 150-200mm rainfall across 9-11 wet days — late-afternoon and evening showers that rinse the temple precinct and the Swarnamukhi river ghat without disrupting morning programmes. Daytime 26-28C, nights 20-21C, humidity 73 percent. The Sri Kalahastiswara Swamy Temple at full ritual tempo. Karthika Masam (the full Karthika lunar month — late October into late November in 2026) brings month-long Shiva observances; the Pancha Bhoota Wind-element Stalam is one of the four major Karthika-Deepam sites in Andhra Pradesh alongside Srisailam, Lepakshi, and Tirumala. Karthika Pournami (the Karthika full moon, mid-November) draws 50,000-100,000 pilgrims for the mass-deepam at sunset — thousands of oil lamps light the temple gopuram and the prakaram simultaneously. Rahu-Ketu Sarpa Dosha pujas at full schedule and at year-densest queue (Karthika Masam is held to be the most auspicious month for Sarpa Dosha remediation alongside Sravana). Patala Ganapati and Sahasralinga shrines at standard schedule.'
)
