INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srikalahasti', 12, 5, 'go',
  'Cool peak. 17-27C. Vaikunta Ekadasi Tirupati spillover Dec 30. Christmas-NYE pilgrim density.',
  'December is the peak-cool month. Daytime 26-27C, nights 17-19C. Tirupati Vaikunta Ekadasi Dec 30 brings 36km-west spillover. Christmas-NYE pilgrim density. Hotel rates at peak.',
  NULL,
  'December in Srikalahasti is the peak-cool month. Rainfall drops to 50-90mm as the northeast monsoon tails off through the first half; the second half is the year''s driest stretch. Daytime 26-27C, nights 17-19C, humidity 60 percent. The Sri Kalahastiswara Swamy Temple at full ritual tempo. The Tirumala Vaikunta Ekadasi (Dec 30 in 2026, 36km west at Tirupati — the Vaikunta Dwaram opens for the 10-day window) brings spillover Vaishnavite pilgrim flow through Srikalahasti as travelers club the Pancha Bhoota Wind temple with Tirumala. Rahu-Ketu Sarpa Dosha pujas (Sadharana ₹250, Madhyama ₹750, Uttama ₹1,500, Visesha ₹2,500) at year-cleanest comfort with the 6-9am Rahu Kalam window booking 2-3 weeks ahead through the Vaikunta corridor. Patala Ganapati shrine (underground Ganesha sanctum, 30 steps below ground) and Sahasralinga panel at full schedule. Dakshinamurthy shrine at standard sequence. Kalamkari workshop visits at year-best — the dry cool air at peak for the natural dye fixing process. APCO Co-operative on Tirupati Road and Sri Padmavathi workshop near temple at full output. Vana Durga Temple (3km) workable through full day.'
)
